var S;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	describe("pulsating sizes of circles from inside cyan outside purple");
	frameRate(60);

  noFill();
	stroke("silver");
  strokeWeight(2);
	S = max(width, height);
  loop();
}

function draw() {
	background(2, 2, 8);
	translate(width/2, height/2)
	rotate(frameCount/87)

	const d = max(width, height) * abs(cos(frameCount/231));
	for (let dd = d; dd > 0; dd -= 10) {
		const f = map(dd, d, 0, 0, 1);
		stroke(lerpColor(color("cyan"), color("rgb(50,4,50)"), 1-f));
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {			
			drawingContext.setLineDash([0]);
			if (dd > 20) drawingContext.setLineDash([~~(sqrt(dd))]);
		}
		circle(0, 0, dd);
	}
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

